def _h(v):
    return hashlib.sha256(json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(',',':'),default=str).encode()).hexdigest()

def ensure_build282_schema(db: Any) -> None:
    db.conn.executescript(SCHEMA)
    for row in CURRICULUM:
        db.conn.execute('INSERT OR IGNORE INTO ai_hard_training_curriculum_282 VALUES(?,?,?,?,?,?,?,?,?)',(*row,_h(row)))
    for row in ROADMAP:
        db.conn.execute('INSERT OR REPLACE INTO ai_training_roadmap_282_300 VALUES(?,?,?,?,?)',row)
    caps=[
      ('phase12_persistent_mission_queue_282','Persistent mission job queue with bounded retries and lease-based recovery.'),
      ('phase12_checkpoint_resume_282','Immutable mission checkpoints and explicit-OK resume contract.'),
      ('phase12_recovery_engine_282','Stale-job recovery without scope expansion or automatic external side effects.'),
      ('ai_hard_training_program_282','Reviewed hard/adversarial benchmark curriculum; performance counted only after recorded evaluation.'),
    ]
    for key,note in caps:
        db.conn.execute('INSERT OR REPLACE INTO capability_manifest_2601(capability_key,introduced_build,status,contract_kind,notes) VALUES(?,?,?,?,?)',(key,'282','active','phase12_contract',note))
    for k,v in (('schema_version','282.0'),('application_build','282.0'),('phase12_status','active'),('phase12_current_build','282.0'),('ai_hard_training_status','curriculum_active')):
        db.conn.execute('INSERT OR REPLACE INTO meta(key,value) VALUES(?,?)',(k,v))
    db.conn.commit()
